import heapq
from collections import defaultdict


def topological_order(nodes, edges):
    node_set = set(nodes)

    # Validate edges: every node referenced must be in node_set
    for before, after in edges:
        if before not in node_set or after not in node_set:
            raise ValueError("Edge contains an unknown node")

    # Build adjacency list and in-degree map, ignoring duplicate edges
    adj = defaultdict(set)
    in_degree = {node: 0 for node in node_set}

    for before, after in edges:
        if after not in adj[before]:
            adj[before].add(after)
            in_degree[after] += 1

    # Kahn's algorithm with a min-heap for lexicographic order
    heap = [node for node in node_set if in_degree[node] == 0]
    heapq.heapify(heap)

    result = []
    while heap:
        node = heapq.heappop(heap)
        result.append(node)
        for neighbor in adj[node]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                heapq.heappush(heap, neighbor)

    if len(result) != len(node_set):
        raise ValueError("Graph has a cycle")

    return result

