def topological_order(nodes, edges):
    known = set(nodes)
    adj = {}
    indegree = {}

    for edge in edges:
        before, after = edge
        if before not in known or after not in known:
            raise ValueError("edge contains an unknown node")

        neighbors = adj.setdefault(before, set())
        if after not in neighbors:
            neighbors.add(after)
            indegree[after] = indegree.get(after, 0) + 1

    heap = [node for node in known if indegree.get(node, 0) == 0]
    heapq.heapify(heap)

    order = []
    while heap:
        node = heapq.heappop(heap)
        order.append(node)

        for nxt in adj.get(node, ()):
            indegree[nxt] -= 1
            if indegree[nxt] == 0:
                heapq.heappush(heap, nxt)

    if len(order) != len(known):
        raise ValueError("graph contains a cycle")

    return order

