        is_async_iterable = False
    except TypeError:
        iterator = items.__aiter__()
        is_async_iterable = True

    results = []
    active = {}
    next_index = 0
    exhausted = False
    first_error = None
    cleaned_up = False

    def _on_task_done(task, idx):
        nonlocal first_error

        try:
            if task.cancelled():
                exc = asyncio.CancelledError()
            else:
                exc = task.exception()
        except Exception as e:
            exc = e

        if exc is not None:
            if first_error is None:
                first_error = exc
            return

        try:
            value = task.result()
        except Exception as e:
            if first_error is None:
                first_error = e
            return

        if idx >= len(results):
            results.extend([None] * (idx - len(results) + 1))
        results[idx] = value

    async def _start_next():
        nonlocal exhausted, next_index

        if exhausted or len(active) >= limit or first_error is not None:
            return

        try:
            if is_async_iterable:
                item = await iterator.__anext__()
            else:
                item = iterator.__next__()
        except StopIteration:
            exhausted = True
            return
        except StopAsyncIteration:
            exhausted = True
            return

        if first_error is not None:
            return

        idx = next_index
        next_index += 1

        task = asyncio.ensure_future(worker(item))
        active[idx] = task
        task.add_done_callback(lambda t, i=idx: _on_task_done(t, i))

    async def _cancel_and_raise():
        nonlocal cleaned_up

        outstanding = list(active.values())
        for task in outstanding:
            if not task.done():
                task.cancel()

        if outstanding:
            await asyncio.gather(*outstanding, return_exceptions=True)

        active.clear()
        cleaned_up = True
        raise first_error

    try:
        while True:
            while len(active) < limit and not exhausted and first_error is None:
                await _start_next()

            if first_error is not None:
                await _cancel_and_raise()

            if exhausted and not active:
                break

            done, _ = await asyncio.wait(
                list(active.values()),
                return_when=asyncio.FIRST_COMPLETED,
            )

            if first_error is None:
                for task in done:
                    try:
                        exc = (
                            asyncio.CancelledError()
                            if task.cancelled()
                            else task.exception()
                        )
                    except Exception as e:
                        exc = e

                    if exc is not None:
                        first_error = exc
                        break

            if first_error is not None:
                await _cancel_and_raise()

            for idx in [i for i, t in active.items() if t in done]:
                del active[idx]
    finally:
        if not cleaned_up:
            outstanding = list(active.values())
            for task in outstanding:
                if not task.done():
                    task.cancel()

            if outstanding:
                await asyncio.gather(*outstanding, return_exceptions=True)

            active.clear()

